const AMP=2.75, FACE=4.6, POW=1.7, BACK=1.45, LIP=0.36, LC=0.28, LS=0.55;
function wall(dz){
  if(dz>=0) return AMP*Math.exp(-(dz*dz)/(2*BACK*BACK));
  const u=Math.min(1,Math.max(0,(dz+FACE)/FACE));
  const e=Math.pow(u,POW);
