}
function lip(dz){const u=dz+LC; return LIP*Math.exp(-(u*u)/(2*LS*LS));}
function h(dz){return wall(dz)+lip(dz);}
function slope(dz){const e=0.05; return (h(dz+e)-h(dz-e))/(2*e);}
