export function oceanHeight(x, z, t) {
  const dz = z - crestZ(x, t);
  let wall;
  if (dz >= 0) {
    wall = WALL_AMP * Math.exp(-(dz * dz) / (2 * SIGMA_BACK * SIGMA_BACK));
