function featherGeometry(length, width, side) {
  const d = side >= 0 ? 1 : -1;
  const s = new THREE.Shape();
  s.moveTo(0, 0);
  s.bezierCurveTo(
    d * length * 0.2, width * 0.62,
    d * length * 0.66, width * 0.38,
    d * length, width * 0.04,
  );
  s.quadraticCurveTo(d * length * 1.04, 0, d * length * 0.9, -width * 0.1);
  s.bezierCurveTo(
    d * length * 0.52, -width * 0.28,
    d * length * 0.14, -width * 0.1,
    0, 0,
  );
  const g = new THREE.ShapeGeometry(s, 5);
  return g;
}

