import * as THREE from "three";
import { poseAt } from "./main.js";
import { createPelican } from "./pelican.js";
import { composeRootQuaternion, rootBasis, WORLD_UP } from "./frame.js";
import { selfTestFrame } from "./frame.js";
selfTestFrame();
const p = createPelican();
const ride = poseAt(3.2, p);
const board = rootBasis(p.root.quaternion, {right:new THREE.Vector3(), up:new THREE.Vector3(), back:new THREE.Vector3(), forward:new THREE.Vector3()});
console.log("board up", board.up.toArray().map(n=>n.toFixed(2)), "fwd", board.forward.toArray().map(n=>n.toFixed(2)));
const uq = composeRootQuaternion(board.forward, WORLD_UP, new THREE.Quaternion());
const camAxes = rootBasis(uq, {right:new THREE.Vector3(), up:new THREE.Vector3(), back:new THREE.Vector3(), forward:new THREE.Vector3()});
const dist = 5.6;
const cam = ride.position.clone().addScaledVector(camAxes.right, -dist*1.05).addScaledVector(camAxes.back, dist*0.12).addScaledVector(WORLD_UP, 1.28);
const look = new THREE.Vector3();
p.lookAnchor.getWorldPosition(look);
const view = look.clone().sub(cam).normalize();
const V = cam.clone().sub(ride.position).normalize();
const N = ride.normal.clone().normalize();
const L = N.clone().multiplyScalar(2*N.dot(V)).sub(V).normalize();
console.log("ny", N.y.toFixed(3), "view", view.toArray().map(n=>n.toFixed(2)).join(","));
console.log("SUN", L.toArray().map(n=>n.toFixed(3)).join(", "), "inFrame", L.dot(view).toFixed(3));
const wing = p.root.getObjectByName ? null : null;
let wingMesh = null;
p.root.traverse(o => { if (o.userData && o.userData.flap && !wingMesh) wingMesh = o; });
const nrm = new THREE.Vector3(1,0,0).applyQuaternion(wingMesh.getWorldQuaternion(new THREE.Quaternion()));
console.log("wing normal", nrm.toArray().map(n=>n.toFixed(2)).join(","), "dot cam", nrm.dot(V).toFixed(2));
'

